#!/usr/bin/env python3
import os, sys, re, datetime, calendar

TODAY=datetime.date.today()
def parse(line):
    s=line.rstrip('\n'); d={'raw':s,'done':False,'pri':'','created':'','finished':'','tags':{}}
    if s.startswith('x '):
        d['done']=True; s=s[2:]
        m=re.match(r'(\d{4}-\d\d-\d\d)(?:\s+|$)',s)
        if m: d['finished']=m.group(1); s=s[m.end():]
    m=re.match(r'\(([A-Z])\)\s*',s)
    if m: d['pri']=m.group(1); s=s[m.end():]
    m=re.match(r'(\d{4}-\d\d-\d\d)(?:\s+|$)',s)
    if m: d['created']=m.group(1); s=s[m.end():]
    d['subject']=s
    for m in re.finditer(r'(?<!\S)([\w!]+):([^\s]+)',s): d['tags'][m.group(1)]=m.group(2)
    d['projects']=re.findall(r'(?<!\S)\+([^\s]+)',s); d['contexts']=re.findall(r'(?<!\S)@([^\s]+)',s)
    d['due']=d['tags'].get('due',''); d['rec']=d['tags'].get('rec','')
    return d
def main():
    args=sys.argv[1:]
    if not args or args[0] in ('-h','--help','help'):
        print('Usage: ttdl command [ID range] [subject] [filter] [new values] [extra options]'); return
    cmd=args.pop(0); cmd={'l':'list','ls':'list','a':'add','d':'done','rm':'remove','e':'edit'}.get(cmd,cmd)
    filename=os.environ.get('TTDL_FILENAME','todo.txt')
    if os.path.isdir(filename): filename=os.path.join(filename,'todo.txt')
    try:
        with open(filename,encoding='utf-8') as f: lines=f.readlines()
    except: lines=[]
    todos=[parse(x) for x in lines]
    if cmd=='add':
        subj=' '.join(a for a in args if not a.startswith('-'))
        if not subj.strip(): print('Subject is empty'); return
        with open(filename,'a',encoding='utf-8') as f: f.write(subj.strip()+'\n')
        todos.append(parse(subj)); idx=len(todos)
        show([todos[-1]], [idx], added=True); return
    if cmd not in ('list','ls','agenda','stats'): return
    all_=('-a' in args or '--all' in args); only_done=('-A' in args or '--only-completed' in args)
    hidden='--hidden' in args
    short='--short' in args
    idset=None; search=[]; projects=[]; contexts=[]; opts={}
    for a in args:
        if a.startswith('--'):
            k,eq,v=a.partition('=');
            if eq: opts[k[2:]]=v
        elif a.startswith('+'): projects.append(a[1:])
        elif a.startswith('@'): contexts.append(a[1:])
        elif re.fullmatch(r'[\d,-]+',a) and any(c.isdigit() for c in a):
            ids=set()
            for p in a.split(','):
                if '-' in p:
                    try:
                        l,r=map(int,p.split('-',1)); ids.update(range(l,r+1))
                    except: pass
                else:
                    try: ids.add(int(p))
                    except: pass
            idset=ids
        elif not a.startswith('-'): search.append(a)
    selected=[]; nums=[]
    for i,d in enumerate(todos,1):
        if not all_ and not only_done and d['done']: continue
        if only_done and not d['done']: continue
        if not hidden and re.search(r'(?<!\S)h:[^\s]+',d['subject']): continue
        if idset is not None and i not in idset: continue
        if projects and not any(any(fnmatch(p,x) for x in d['projects']) for p in projects): continue
        if contexts and not any(any(fnmatch(p,x) for x in d['contexts']) for p in contexts): continue
        hay=(d['subject']+' '+' '.join(d['projects'])+' '+' '.join(d['contexts'])).lower()
        if search and not any(q.lower() in hay for q in search): continue
        pri=opts.get('pri')
        if pri:
            p=d['pri']; pv=ord(p.lower()) if p else 0
            if pri=='none' and p or pri=='any' and not p: continue
            if re.fullmatch('[a-z]',pri) and p.lower()!=pri: continue
            if pri.endswith('+') and pv>ord(pri[0]): continue
            if pri.endswith('-') and (not p or pv<ord(pri[0])): continue
        due=opts.get('due')
        if due:
            if due=='none' and d['due'] or due=='any' and not d['due']: continue
            if due in ('today','tomorrow','yesterday','overdue','soon'):
                try: delta=(datetime.date.fromisoformat(d['due'])-TODAY).days
                except: delta=99999
                if due=='today' and delta!=0 or due=='tomorrow' and delta!=1 or due=='yesterday' and delta!=-1 or due=='overdue' and delta>=0 or due=='soon' and not (0<=delta<=7): continue
        selected.append(d); nums.append(i)
    if cmd=='list': show(selected,nums,short=short,total=len(todos))
def fnmatch(pattern,value):
    import fnmatch as f
    return f.fnmatchcase(value.lower(),pattern.lower())
def show(ds,nums,short=False,total=None,added=False):
    if short:
        h=' # D P Subject'; sep='---------------'
        print(h); print(sep)
        for i,d in zip(nums,ds): print(f"{i:2} {'x' if d['done'] else ('R' if d['rec'] else ' ')} {d['pri'] or ' '} {d['subject']}")
    else:
        h=' # D P Created    Finished Due        Subject'; print(h); print('-'*len(h))
        for i,d in zip(nums,ds): print(f"{i:2} {'x' if d['done'] else ('R' if d['rec'] else ' ')} {d['pri'] or ' '} {d['created']:<10} {d['finished']:<10} {d['due']:<10} {d['subject']}")
    print('-'*(15 if short else len(h)));
    if not added and total is not None: print(f'{len(ds)} todos (of {total} total)')
if __name__=='__main__': main()

