"""Date parsing helpers for TTDL's todo date expressions and filters."""
from __future__ import annotations

from datetime import date, timedelta
import calendar
import re

_DURATION = re.compile(r'([+-]?\d+)([dwmy]?)')
_WEEKDAYS = {'mon': 0, 'tue': 1, 'wed': 2, 'thu': 3, 'fri': 4, 'sat': 5, 'sun': 6}


def add_months(day: date, count: int) -> date:
    """Add calendar months, keeping end-of-month dates at month end."""
    was_last = day.day == calendar.monthrange(day.year, day.month)[1]
    n = day.year * 12 + day.month - 1 + count
    year, month0 = divmod(n, 12)
    month = month0 + 1
    end = calendar.monthrange(year, month)[1]
    return date(year, month, end if was_last else min(day.day, end))


def add_duration(day: date, amount: int, unit: str = 'd') -> date:
    if unit == 'd':
        return day + timedelta(days=amount)
    if unit == 'w':
        return day + timedelta(days=amount * 7)
    if unit == 'm':
        return add_months(day, amount)
    if unit == 'y':
        return add_months(day, amount * 12)
    raise ValueError(f'unknown date unit: {unit}')


def parse_duration(value: str) -> date:
    """Parse a relative duration such as -2d, 1m2w, or 1y from today."""
    return apply_duration(date.today(), value)


def apply_duration(day: date, value: str) -> date:
    if not value:
        return day
    pos = 0
    matches = list(_DURATION.finditer(value))
    if not matches or ''.join(m.group(0) for m in matches) != value:
        raise ValueError(f'invalid duration: {value}')
    for m in matches:
        amount = int(m.group(1))
        unit = m.group(2) or 'd'
        day = add_duration(day, amount, unit)
    return day


def parse_human_date(value: str, today: date | None = None) -> date | None:
    """Parse the documented relative/special date syntax; None represents 'none'."""
    today = today or date.today()
    val = value.lower().strip()
    if val == 'none':
        return None
    if val == 'today':
        return today
    if val == 'tomorrow':
        return today + timedelta(days=1)
    if val == 'yesterday':
        return today - timedelta(days=1)
    if val == 'first':
        return add_months(today.replace(day=1), 1)
    if val == '-first':
        ref = today.replace(day=1) - timedelta(days=1) if today.day == 1 else today
        return ref.replace(day=1)
    if val == 'last':
        end = calendar.monthrange(today.year, today.month)[1]
        ref = add_months(today.replace(day=1), 1) if today.day == end else today
        return ref.replace(day=calendar.monthrange(ref.year, ref.month)[1])
    if val == '-last':
        prev = today.replace(day=1) - timedelta(days=1)
        return prev.replace(day=calendar.monthrange(prev.year, prev.month)[1])
    if val in _WEEKDAYS:
        diff = (_WEEKDAYS[val] - today.weekday()) % 7
        return today + timedelta(days=diff or 7)
    if val.startswith('-') and val[1:] in _WEEKDAYS:
        diff = (today.weekday() - _WEEKDAYS[val[1:]]) % 7
        return today - timedelta(days=diff or 7)
    try:
        return date.fromisoformat(val)
    except ValueError:
        pass
    # Relative values like 1m2w and -3d.
    if re.fullmatch(r'[+-]?\d+[dwmy](?:\d+[dwmy])*', val):
        return apply_duration(today, val)
    raise ValueError(f'invalid date: {value}')


def parse_date_expression(expr: str, today: date | None = None, tags: dict[str, str] | None = None) -> date:
    """Evaluate `base+duration-duration`; bases may reference date tags."""
    today = today or date.today()
    tags = tags or {}
    # Consume an ISO date (whose separators are also hyphens) or a tag/base
    # token, then parse explicit +/- duration operations.
    m = re.match(r"(\d{4}-\d{2}-\d{2}|[A-Za-z_][A-Za-z0-9_-]*)(.*)$", expr)
    if not m:
        raise ValueError(f'invalid date expression: {expr}')
    base, rest = m.group(1), m.group(2)
    if base.lower() in ('today', 'tomorrow', 'yesterday') or base.lower() in _WEEKDAYS:
        result = parse_human_date(base, today)
    elif base.lower() in tags:
        result = parse_date_expression(tags[base.lower()], today, tags)
    else:
        result = date.fromisoformat(base)
    if result is None:
        raise ValueError(f'date expression has no base date: {expr}')
    while rest:
        m = re.match(r'([+-])(\d+)([dwmy]?)', rest)
        if not m:
            raise ValueError(f'invalid date expression: {expr}')
        result = add_duration(result, int(m.group(2)) * (1 if m.group(1) == '+' else -1), m.group(3) or 'd')
        rest = rest[m.end():]
    return result


def parse_date_range(value: str, today: date | None = None) -> tuple[date | None, date | None, bool]:
    """Return inclusive bounds and whether unset dates are included.

    Accepts a single date or an open/closed range separated by `..` or `:`.
    """
    today = today or date.today()
    # A trailing `..` is accepted by TTDL's relative-window shorthand,
    # e.g. `..2d..` means any date through two days from today.
    if value.endswith('..') and value.count('..') == 2:
        middle = value[2:-2]
        upper = parse_human_date(middle, today)
        return None, upper, False
    sep = '..' if '..' in value else ':' if ':' in value else None
    if not sep:
        point = parse_human_date(value, today)
        return point, point, point is None
    left, right = value.split(sep, 1)
    a = parse_human_date(left, today) if left else None
    b = parse_human_date(right, today) if right else None
    include_none = left.strip().lower() == 'none' or right.strip().lower() == 'none'
    if a is not None and b is not None and a > b:
        a, b = b, a
    return a, b, include_none

